#!/usr/bin/env node
/**
 * Writes src/theme-localai.css from src/theme/theme-localai.json.
 *
 * The JSON is the one source of the palette. It is a copy of the LocalAI theme
 * file of the branding kit (tokens/theme-localai.json), taken as is: when the
 * kit changes the palette, copy the new file over src/theme/theme-localai.json
 * and run this script. Do not edit the colours here. Its "version" field says
 * which kit state the copy follows.
 *
 * The CSS has the three blocks the kit contract asks for: light on :root, dark
 * under the OS setting when the page has no data-theme, and dark under
 * data-theme="dark". They are written from the same dark map, so the two dark
 * blocks cannot differ.
 *
 *   node scripts/gen-theme.mjs           # write the CSS
 *   node scripts/gen-theme.mjs --check   # exit 1 when the CSS is out of date
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const SOURCE = join(ROOT, 'src/theme/theme-localai.json')
const OUT = join(ROOT, 'src/theme-localai.css')

const block = (map, pad) => Object.entries(map).map(([k, v]) => `${' '.repeat(pad)}--dk-${k}: ${v};`).join('\n')

export function buildCss(theme) {
  const brand = Object.entries(theme.brand).map(([k, v]) => `  --brand-${k}: ${v};`).join('\n')
  return (
    `/* LocalAI theme for the kit roles (src/vendor/ui-kit/theme-contract.md).\n` +
    `   Generated by scripts/gen-theme.mjs from src/theme/theme-localai.json: do not edit by hand.\n` +
    `   The JSON is a copy of the branding kit's theme file (version ${theme.version}); to change a\n` +
    `   colour, change it in the kit, copy the file over and run the script.\n` +
    `   The --brand-* variables are the raw brand colours. Pages use the --dk-* roles, never these.\n` +
    `   The app always sets data-theme on <html> (index.html does it before first paint); the\n` +
    `   media block covers only a page without the attribute. */\n` +
    `:root {\n${brand}\n${block(theme.light, 2)}\n}\n\n` +
    `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n${block(theme.dark, 4)}\n  }\n}\n\n` +
    `:root[data-theme="dark"] {\n${block(theme.dark, 2)}\n}\n`
  )
}

export function loadTheme() {
  return JSON.parse(readFileSync(SOURCE, 'utf8'))
}

export function isCurrent() {
  return existsSync(OUT) && readFileSync(OUT, 'utf8') === buildCss(loadTheme())
}

if (process.argv[1] && process.argv[1].endsWith('gen-theme.mjs')) {
  if (process.argv.includes('--check')) {
    if (!isCurrent()) {
      console.error('src/theme-localai.css is out of date: run node scripts/gen-theme.mjs')
      process.exit(1)
    }
    console.log('theme css is up to date')
  } else {
    writeFileSync(OUT, buildCss(loadTheme()))
    console.log('wrote src/theme-localai.css')
  }
}
